:root { font-family: system-ui, sans-serif; color: #17263b; background: #f5f7fb; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 800px; margin: 3rem auto; padding: 0 1.25rem; }
h1 { font-size: 2.25rem; overflow-wrap: anywhere; }
h2 { margin-top: 2.5rem; }
label { display: block; font-weight: 600; margin-bottom: .5rem; }
.input-group { display: flex; gap: .75rem; }
input { min-width: 0; flex: 1; padding: .75rem; border: 1px solid #7a8798; border-radius: .4rem; font: inherit; }
button { font: inherit; font-weight: 600; border: 1px solid #254bbb; border-radius: .4rem; padding: .75rem 1rem; background: #254bbb; color: white; cursor: pointer; }
button:hover { background: #19368b; }
:focus-visible { outline: 3px solid #c17100; outline-offset: 3px; }
.project-list { list-style: none; padding: 0; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem; background: white; border: 1px solid #cbd3df; border-radius: .5rem; margin-bottom: .75rem; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row form { flex-shrink: 0; }
[role="alert"] { color: #a11a1a; font-weight: 600; }
.empty { color: #526075; }
@media (max-width: 480px) { .input-group { flex-direction: column; } main { margin-top: 1.5rem; } }

